# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: shape
def shape(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(emit(intake(render(gather(raw)))))

